import { ethers, keccak256 } from "ethers";

export const buildBytecode = (
  constructorTypes: any[],
  constructorArgs: any[],
  contractBytecode: string
) =>
  `${contractBytecode}${encodeParams(constructorTypes, constructorArgs).slice(
    2
  )}`;

const buildCreate2Address = (
  factoryAddress: string,
  saltHex: string,
  byteCode: string
) => {
  return `0x${keccak256(
    `0x${["ff", factoryAddress, saltHex, keccak256(byteCode)]
      .map((x) => x.replace(/0x/, ""))
      .join("")}`
  ).slice(-40)}`.toLowerCase();
};

const saltToHex = (salt: string | number) => ethers.id(salt.toString());

const encodeParams = (dataTypes: any[], data: any[]) => {
  const abiCoder = new ethers.AbiCoder();
  return abiCoder.encode(dataTypes, data);
};

export function getCreate2Address({
  factoryAddress,
  salt,
  contractBytecode,
  constructorTypes = [] as string[],
  constructorArgs = [] as any[],
}: {
  salt: string | number;
  factoryAddress: string;
  contractBytecode: string;
  constructorTypes?: string[];
  constructorArgs?: any[];
}) {
  return buildCreate2Address(
    factoryAddress,
    saltToHex(salt),
    buildBytecode(constructorTypes, constructorArgs, contractBytecode)
  );
}

// import
import { ethers } from "ethers";
import { getCreate2Address } from "./create2";

// declare deployment parameters
import contractArtifact from "./artifact.json";

const constructorTypes = contractArtifact.abi
  .find((v) => v.type === "constructor")
  ?.inputs.map((t) => t.type);

export const factoryAddress = "0xc07c1980C87bfD5de0DC77f90Ce6508c1C0795C3";
const constructorArgs: any[] = [
  "0x1a44076050125825900e736c501f859c50fE728c",
  "0xe5159e75ba5f1C9E386A3ad2FC7eA75c14629572",
];

console.log("constructor parameters", constructorTypes, constructorArgs);

const job = () => {
  let i = 0;

  while (true) {
    const salt = ethers.id("" + i);
    // Calculate contract address
    const computedAddress = getCreate2Address({
      salt: salt,

      factoryAddress,
      contractBytecode: contractArtifact.bytecode,
      constructorTypes: constructorTypes,
      constructorArgs: constructorArgs,
    });

    if (
      computedAddress.startsWith("0x0000") &&
      computedAddress.endsWith("0000")
    ) {
      console.log("found the right salt hash");
      console.log("salt", salt, computedAddress);
      break;
    }

    if (i % 100000 == 0) console.log(i, "salt", salt, computedAddress);
    i++;
  }
};

job();
